                continue
            if in_test:
                brace_count += line.count('{') - line.count('}')
                if brace_count <= 0 and '{' not in line and '}' in line:
                    in_test = False
                continue
            if '.unwrap()' in line and '//' not in line.split('.unwrap()')[0]:
                print(f'{path}:{i}: {line.strip()}')
"

