python3 -c "
import re, os

# Find all .rs files
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()

        # Remove test modules
        # Simple heuristic: find #[cfg(test)] and remove from there to the matching }
        lines = content.split('\n')
        in_test = False
        brace_count = 0
        non_test_lines = []
        for i, line in enumerate(lines, 1):
            if '#[cfg(test)]' in line:
                in_test = True
                brace_count = 0
                continue
            if in_test:
                brace_count += line.count('{') - line.count('}')
                if brace_count <= 0 and '{' not in line and '}' in line:
                    in_test = False
                continue
            if '.unwrap()' in line and '//' not in line.split('.unwrap()')[0]:
                print(f'{path}:{i}: {line.strip()}')
"

